// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        // admissible, wide domain
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 10 ether);
        unlockTime = bound(unlockTime, 1, type(uint64).max);

        // fund the actor and make the deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (uint256 storedUnlock, uint256 storedBalance) = c.Acc(actor);
        vm.assume(storedBalance >= c.MinSum());

        // act exactly at the stored unlock time
        vm.warp(storedUnlock);
        vm.prank(actor);
        c.Collect(amount);

        // rule: at t == unlockTime the balance must be unchanged
        (uint256 postUnlock, uint256 postBalance) = c.Acc(actor);
        assertTrue(postBalance == storedBalance);
    }
}
